import React from 'react';
import { getImageUrl, getDefaultAvatar } from '../config';
import './Sidebar.css';

function Sidebar({ currentPage, onPageChange, user, onProfileClick, badges = {} }) {
    const menuItems = [
        {
            id: 'dashboard',
            name: 'لوحة التحكم',
            icon: '📊',
            adminOnly: false
        },
        {
            id: 'users',
            name: 'إدارة المستخدمين',
            icon: '👥',
            adminOnly: true
        },
        {
            id: 'conversations',
            name: 'المحادثات',
            icon: '💬',
            adminOnly: true
        },
        {
            id: 'chat-rooms',
            name: 'غرف المحادثة',
            icon: '🏠',
            adminOnly: true
        },
        {
            id: 'reports',
            name: 'الإشراف والمخالفات',
            icon: '🛡️',
            adminOnly: true
        },
        {
            id: 'appeals',
            name: 'طلبات الاستئناف',
            icon: '📝',
            adminOnly: true
        },
        {
            id: 'banned-devices',
            name: 'الأجهزة المحظورة',
            icon: '📵',
            adminOnly: true
        },
        {
            id: 'banned-ips',
            name: 'IPs المحظورة',
            icon: '🌐',
            adminOnly: true
        },
        {
            id: 'admin-activity',
            name: 'سجل نشاط الأدمن',
            icon: '📜',
            adminOnly: true
        },
        {
            id: 'users-map',
            name: 'خريطة المستخدمين',
            icon: '🗺️',
            adminOnly: true
        },
        {
            id: 'super-likes',
            name: 'Super Likes',
            icon: '⚡',
            adminOnly: true
        },
        {
            id: 'verification-requests',
            name: 'طلبات التوثيق',
            icon: '✅',
            adminOnly: true
        },
        {
            id: 'stats',
            name: 'الإحصائيات',
            icon: '📈',
            adminOnly: true
        },
        {
            id: 'settings',
            name: 'الإعدادات',
            icon: '⚙️',
            adminOnly: true
        }
    ];

    const isAdmin = user?.role === 'admin';

    // تمييز العنصر الصحيح حتى عند التنقل من Dashboard بمعرّف قديم
    const isActive = (itemId) => {
        if (currentPage === itemId) return true;
        if (itemId === 'users' && currentPage === 'premium-users') return true;
        if (itemId === 'chat-rooms' && currentPage === 'categories') return true;
        if (itemId === 'reports' && currentPage === 'flagged-messages') return true;
        if (itemId === 'reports' && currentPage === 'banned-words') return true;
        if (itemId === 'reports' && currentPage === 'name-blocking') return true;
        return false;
    };

    return (
        <div className="sidebar">
            <div className="sidebar-header" onClick={() => onPageChange('dashboard')} style={{ cursor: 'pointer' }}>
                <img src="/favicon.svg" alt="شات هلا" className="sidebar-logo" />
                <h2>شات هلا</h2>
                <p>لوحة التحكم</p>
            </div>

            <nav className="sidebar-nav">
                {menuItems.map((item) => {
                    // إخفاء العناصر المخصصة للأدمن من المستخدمين العاديين
                    if (item.adminOnly && !isAdmin) {
                        return null;
                    }

                    const badgeCount = badges[item.id] || 0;
                    return (
                        <button
                            key={item.id}
                            className={`nav-item ${isActive(item.id) ? 'active' : ''} ${item.disabled ? 'disabled' : ''}`}
                            onClick={() => !item.disabled && onPageChange(item.id)}
                            disabled={item.disabled}
                        >
                            <span className="nav-icon">{item.icon}</span>
                            <span className="nav-name">{item.name}</span>
                            {badgeCount > 0 && (
                                <span
                                    style={{
                                        background: '#ef4444',
                                        color: '#fff',
                                        fontSize: '11px',
                                        fontWeight: '700',
                                        minWidth: '20px',
                                        height: '20px',
                                        borderRadius: '10px',
                                        padding: '0 6px',
                                        display: 'inline-flex',
                                        alignItems: 'center',
                                        justifyContent: 'center',
                                        marginInlineStart: 'auto',
                                        boxShadow: '0 0 0 2px #ffffff20'
                                    }}
                                    title={`${badgeCount} عنصر في الانتظار`}
                                >
                                    {badgeCount > 99 ? '99+' : badgeCount}
                                </span>
                            )}
                            {item.disabled && <span className="coming-soon">قريباً</span>}
                        </button>
                    );
                })}
            </nav>

            <div className="sidebar-footer">
                <div className="user-info" onClick={onProfileClick} style={{ cursor: 'pointer' }} title="عرض الملف الشخصي">
                    <img
                        src={user?.profileImage ? getImageUrl(user.profileImage) : getDefaultAvatar(user?.name)}
                        alt={user?.name || 'User'}
                        className="user-avatar user-avatar-img"
                        onError={(e) => {
                            e.target.onerror = null;
                            e.target.src = getDefaultAvatar(user?.name);
                        }}
                    />
                    <div className="user-details">
                        <p className="user-name">{user?.name || 'Admin'}</p>
                        <p className="user-role">
                            {isAdmin ? 'مدير' : 'مستخدم'}
                        </p>
                    </div>
                </div>
            </div>
        </div>
    );
}

export default Sidebar;
